CREATE TEMP TABLE s503c_cards (id bigint, s_ed text, s_book text, src_ch int, src_vn int, src_text text, t_ed text, tgt_book text, tgt_ch int, tgt_vn int, old_note text, new_note text, thread_id bigint, old_mnote text, new_mnote text) ON COMMIT DROP;
INSERT INTO s503c_cards VALUES
(3048,'canon','matthew',26,36,$n$Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.$n$,'canon','mark',14,32,$n$The Markan-parallel.$n$,$n$Mark 14:32 — *And they came to a place which was named Gethsemane: and he saith to his disciples, Sit ye here, while I shall pray.* *Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.* (Matthew 26:36) Mark sets the same garden and the same words. Yahusha (Jesus) leaves the disciples sitting and goes off to pray, and Mark has him say it just as Matthew does, *Sit ye here*. Two witnesses agree on the place and on what he came there to do.$n$,7,$n$The Markan-parallel.$n$,$n$Mark 14:32 — *he saith to his disciples, Sit ye here, while I shall pray.* Mark names the same place and the same instruction, and says the going apart was for prayer.$n$),
(3049,'canon','matthew',26,36,$n$Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.$n$,'canon','luke',22,39,$n$The Lukan-parallel + the angel + the bloody-sweat.$n$,$n$Luke 22:39 — *And he came out, and went, as he was wont, to the mount of Olives; and his disciples also followed him.* *Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.* (Matthew 26:36) Luke tells where Gethsemane sat. It was on the mount of Olives, and he went there *as he was wont*, the way he always did. So the garden was no sudden turning. He walked to his usual place with the disciples following, and there the cup was waiting.$n$,7,$n$The Lukan-parallel + the substantial-angel-substance + the *bloody sweat* substance.$n$,$n$Luke 22:39 — *as he was wont, to the mount of Olives; and his disciples also followed him.* Luke places the garden on the mount of Olives, where he went by habit, with the disciples following behind him.$n$),
(3050,'canon','matthew',26,36,$n$Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.$n$,'canon','john',18,1,$n$The Yochanan-narrative.$n$,$n$John 18:1 — *When Yahusha (Jesus) had spoken these words, he went forth with his disciples over the brook Cedron, where was a garden, into the which he entered, and his disciples.* *Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.* (Matthew 26:36) John gives the garden its ground. Yahusha (Jesus) had finished speaking to his disciples, and he crossed the brook Cedron and went into a garden. Matthew gives only the name Gethsemane. John says it lay over the brook, a real place with a real way to it.$n$,7,$n$The Yochanan-narrative-substance.$n$,$n$John 18:1 — *he went forth with his disciples over the brook Cedron, where was a garden.* John names the garden across the brook Cedron, the same place Matthew calls Gethsemane.$n$),
(3051,'canon','matthew',26,36,$n$Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.$n$,'canon','psalms',42,5,$n$*Why art thou cast down, O my soul?*$n$,$n$Psalm 42:5 — *Why art thou cast down, O my soul? and why art thou disquieted in me? hope thou in Elohim (God): for I shall yet praise him for the help of his countenance.* *Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.* (Matthew 26:36) Before Yahusha (Jesus) says his soul is sorrowful, the psalmist asks his own soul why it is *cast down*. It is the same weight on the same soul, and the psalm already has the answer: *hope thou in Elohim (God)*. The soul that is low is told where to look.$n$,7,$n$*Why art thou cast down, O my soul?*$n$,$n$Psalm 42:5 — *Why art thou cast down, O my soul? and why art thou disquieted in me.* The psalmist's soul is cast down and told to hope in Elohim (God), the same weight Yahusha (Jesus) carries into the garden.$n$),
(3052,'canon','matthew',26,36,$n$Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.$n$,'canon','psalms',42,11,$n$*Why art thou cast down, O my soul?*$n$,$n$Psalm 42:11 — *Why art thou cast down, O my soul? and why art thou disquieted within me? hope thou in Elohim (God): for I shall yet praise him, who is the health of my countenance, and my Elohim (God).* *Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.* (Matthew 26:36) The psalm says it twice. At its close the cast down soul is asked its question again, and the answer holds: *hope thou in Elohim (God)*. Yahusha (Jesus) goes to a garden to pray with his soul under that same weight, and the psalm has already shown where a soul like that turns.$n$,7,$n$*Why art thou cast down, O my soul?*$n$,$n$Psalm 42:11 — *for I shall yet praise him, who is the health of my countenance, and my Elohim (God).* The refrain comes round again and ends in praise, showing where the troubled soul looks when it is cast down.$n$),
(3053,'canon','matthew',26,36,$n$Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.$n$,'canon','psalms',43,5,$n$The substantial-substance-of-the-Tanakh-psalmist-soul-substance.$n$,$n$Psalm 43:5 — *Why art thou cast down, O my soul? and why art thou disquieted within me? hope in Elohim (God): for I shall yet praise him, who is the health of my countenance, and my Elohim (God).* *Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.* (Matthew 26:36) A third time the psalmist stops and talks to his own soul. Heavy and low, it is told to hope in Elohim (God) and to praise him yet. That is the road Yahusha (Jesus) takes into the garden. His sorrow goes up to the Father and does not go away from him.$n$,7,$n$The substantial-substance-of-the-Tanakh-psalmist-soul-substance.$n$,$n$Psalm 43:5 — *hope in Elohim (God): for I shall yet praise him, who is the health of my countenance.* The refrain returns a third time, again telling the cast down soul to hope in Elohim (God).$n$),
(3054,'canon','matthew',26,36,$n$Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.$n$,'canon','psalms',75,8,$n$The cup-substance.$n$,$n$Psalm 75:8 — *For in the hand of Yahuah (LORD) there is a cup, and the wine is red; it is full of mixture; and he poureth out of the same: but the dregs thereof, all the wicked of the earth shall wring them out, and drink them.* *Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.* (Matthew 26:36) Here is the cup, and it is already in a hand. It is in the hand of Yahuah (LORD), red wine full of mixture, poured out, with the dregs for the wicked to drink. When Yahusha (Jesus) goes off to pray, the cup he will name was not made up that night. It was the Father's to pour.$n$,7,$n$*In the hand of Yahuah (the LORD) there is a cup.*$n$,$n$Psalm 75:8 — *in the hand of Yahuah (LORD) there is a cup, and the wine is red.* The cup is held in the hand of Yahuah (LORD) long before the garden, red and full of mixture.$n$),
(3055,'canon','matthew',26,36,$n$Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.$n$,'canon','isaiah',51,17,$n$The cup-of-trembling substance.$n$,$n$Isaiah 51:17 — *Awake, awake, stand up, O Jerusalem, which hast drunk at the hand of Yahuah (LORD) the cup of his fury; thou hast drunken the dregs of the cup of trembling, and wrung them out.* *Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.* (Matthew 26:36) Jerusalem drank this cup first. Isaiah tells her to wake and stand up, because she had drunk from the hand of Yahuah (LORD) *the cup of his fury* down to the dregs. This is the cup under the prayer in the garden. Matthew did not make it up; Isaiah had it in the hand of Yahuah (LORD) first.$n$,7,$n$*The cup of trembling, even the dregs of the cup of my fury.*$n$,$n$Isaiah 51:17 — *which hast drunk at the hand of Yahuah (LORD) the cup of his fury.* Jerusalem has already drunk the cup of fury from the hand of Yahuah (LORD), the same cup Yahusha (Jesus) later prays over.$n$),
(3056,'canon','matthew',26,36,$n$Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.$n$,'canon','isaiah',51,22,$n$The cup-of-trembling substance.$n$,$n$Isaiah 51:22 — *Thus saith thy Yahuah (Lord) Yahuah (LORD), and thy Elohim (God) that pleadeth the cause of his people, Behold, I have taken out of thine hand the cup of trembling, even the dregs of the cup of my fury; thou shalt no more drink it again:* *Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.* (Matthew 26:36) The cup is taken *out of thine hand*, and Jerusalem is told she will drink it no more. Isaiah says it leaves her hand. In the garden it is Yahusha (Jesus) who takes it up, so the prayer over the cup is a prayer over this very cup.$n$,7,$n$*The cup of trembling, even the dregs of the cup of my fury.*$n$,$n$Isaiah 51:22 — *I have taken out of thine hand the cup of trembling, even the dregs of the cup of my fury.* The cup is lifted out of Jerusalem's hand with a promise she will not drink it again, and the garden puts it into his.$n$),
(3057,'canon','matthew',26,36,$n$Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.$n$,'canon','jeremiah',25,15,$n$The wine-cup-of-fury substance.$n$,$n$Jeremiah 25:15 — *For thus saith Yahuah Elohim (the LORD God) of Yashar'el (Israel) unto me; Take the wine cup of this fury at my hand, and cause all the nations, to whom I send thee, to drink it.* *Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.* (Matthew 26:36) The cup passes from a hand again. Yahuah (LORD) tells Jeremiah to *Take the wine cup of this fury at my hand* and carry it out. It is always his cup, and it is given out by him. So the cup Yahusha (Jesus) speaks of in the garden has a long line of hands, and the first hand is the Father's.$n$,7,$n$*Take the wine cup of this fury at my hand.*$n$,$n$Jeremiah 25:15 — *Take the wine cup of this fury at my hand, and cause all the nations.* The cup of fury is handed out from the hand of Yahuah (LORD) himself, so the cup in the garden is his to give.$n$),
(3058,'canon','matthew',26,36,$n$Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.$n$,'canon','john',12,27,$n$*Now is my soul troubled* — the Yochanan-parallel of-the-soul-troubled-substance.$n$,$n$John 12:27 — *Now is my soul troubled; and what shall I say? Father, save me from this hour: but for this cause came I unto this hour.* *Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.* (Matthew 26:36) John gives the same troubled soul and the same turn. Yahusha (Jesus) asks what he should say, and what he says is *Father, save me from this hour*. Then he names why he is there: *for this cause came I unto this hour*. He does not run. The troubled soul goes to the Father.$n$,7,$n$*Now is my soul troubled* — the Yochanan-parallel of-the-soul-troubled-substance.$n$,$n$John 12:27 — *Father, save me from this hour: but for this cause came I unto this hour.* Yahusha (Jesus) says his soul is troubled and asks the Father to save him from the hour, then names it as the reason he came.$n$),
(3060,'canon','matthew',26,36,$n$Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.$n$,'canon','philippians',2,5,$n$The substantial-Son's-substantial-substance-of-the-substantial-incarnation-substance + obedience-unto-death.$n$,$n$Philippians 2:5 — *Let this mind be in you, which was also in HaMashiach Yahusha (Christ Jesus):* *Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.* (Matthew 26:36) Paul points at Yahusha (Jesus) and tells the saints to carry the mind he had. Read beside the garden, that mind is the Son who asks the Father and then bows his own will to the Father's will. It is a low and willing mind, and it holds all the way to the cross.$n$,7,$n$The substantial-Son's-substantial-substance-of-the-substantial-incarnation-substance + obedience-unto-death.$n$,$n$Philippians 2:5 — *Let this mind be in you, which was also in HaMashiach Yahusha (Christ Jesus).* Paul tells them to have the mind that was in Yahusha (Jesus), the mind that bows to the Father in the garden.$n$),
(3061,'canon','matthew',26,36,$n$Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.$n$,'canon','matthew',20,22,$n$*Are ye able to drink of the cup that I shall drink of?*$n$,$n$Matthew 20:22 — *But Yahusha (Jesus) answered and said, Ye know not what ye ask. Are ye able to drink of the cup that I shall drink of, and to be baptized with the baptism that I am baptized with? They say unto him, We are able.* *Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.* (Matthew 26:36) Before the garden he had already named the cup. Two brothers ask for seats, and he asks them, *Are ye able to drink of the cup*? They say *We are able*. They did not know what they asked. The cup was his to drink, and he was walking toward it with his eyes open.$n$,7,$n$*Are ye able to drink of the cup that I shall drink of?*$n$,$n$Matthew 20:22 — *Are ye able to drink of the cup that I shall drink of.* Yahusha (Jesus) already speaks of the cup as his own to drink, and asks if the sons of Zebedee can share it.$n$),
(3062,'canon','matthew',26,36,$n$Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.$n$,'canon','matthew',4,1,$n$The wilderness-temptation substance — the substantial-precursor.$n$,$n$Matthew 4:1 — *Then was Yahusha (Jesus) led up of the Spirit into the wilderness to be tempted of the devil.* *Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.* (Matthew 26:36) Matthew tells at the start that Yahusha (Jesus) was *led up of the Spirit* into the wilderness to be tempted. The garden is another hard place he goes into on purpose. He is brought to both, and in both he does not turn aside. The hour in the garden is not the first time his obedience is tested.$n$,7,$n$The wilderness-temptation substance — the substantial-precursor.$n$,$n$Matthew 4:1 — *was Yahusha (Jesus) led up of the Spirit into the wilderness to be tempted.* He was led into the wilderness to be tempted, so the testing in the garden is not the first time he is led into a hard place.$n$),
(3063,'canon','matthew',26,36,$n$Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.$n$,'canon','john',10,17,$n$*No man taketh it from me, but I lay it down of myself.*$n$,$n$John 10:17 — *Therefore doth my Father love me, because I lay down my life, that I might take it again.* *Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.* (Matthew 26:36) He says the Father loves him because he lays down his life. That is the garden said ahead of time. He is not caught and dragged. He gives himself, and he gives himself to the Father, who loves him for it. The cup is drunk by choice, and the choosing is a Son answering his Father.$n$,7,$n$*No man taketh it from me, but I lay it down of myself.*$n$,$n$John 10:17 — *doth my Father love me, because I lay down my life, that I might take it again.* The Father's love is tied to the Son laying down his life, which makes the garden a gift given and not a loss taken.$n$),
(3064,'canon','matthew',26,36,$n$Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.$n$,'canon','genesis',22,1,$n$The substantial-Aqedat-Yitschaq (binding of Isaac) substance — the substantial-Tanakh-typology.$n$,$n$Genesis 22:1 — *And it came to pass after these things, that Elohim (God) did tempt Abraham, and said unto him, Abraham: and he said, Behold, here I am.* *Then comes Yahusha (Jesus) with them unto a place called Gethsemane, and says unto the disciples, Sit you here, while I go and pray yonder.* (Matthew 26:36) Elohim (God) tests Abraham, and Abraham answers, *Behold, here I am*. The very next word is about taking his son. Set that beside the garden and the two sit together: a father's word, a son going toward it, and an answer that does not argue. Matthew does not say the word. Put the two side by side.$n$,7,$n$The substantial-Aqedat-Yitschaq (binding of Isaac) substance — the substantial-Tanakh-typology.$n$,$n$Genesis 22:1 — *Elohim (God) did tempt Abraham, and said unto him, Abraham: and he said, Behold, here I am.* Elohim (God) tests Abraham and he answers here I am, the start of the offering of his only son that the garden sits beside.$n$),
(7115,'canon','luke',22,42,$n$Saying, Father, if you be willing, remove this cup from me: nevertheless not my will, but yours, be done.$n$,'canon','matthew',26,39,$n$thread:gethsemane-cup-of-suffering-and-the-sons-substantial-submission-to-the-father | *Father, if thou be willing, remove this cup from me: nevertheless not my will, but thine, be done* (Luke 22:42). The Gethsemane prayer — the Formed-Son's substantial submission to the Formless-Father over the cup. The cup-of-the-Father's-wrath the King about to drink, named in Yeshayahu (Isaiah) 51:17, 22; Yirmeyahu (Jeremiah) 25:15. The synoptic parallel at Matthew 26:39 carries the same Father-Son submission-substance.$n$,$n$Matthew 26:39 — *And he went a little further, and fell on his face, and prayed, saying, O my Father, if it be possible, let this cup pass from me: nevertheless not as I will, but as thou wilt.* *Saying, Father, if you be willing, remove this cup from me: nevertheless not my will, but yours, be done.* (Luke 22:42) Matthew gives the same prayer in his own words. *O my Father, if it be possible*, let this cup pass, and then the turn, *not as I will, but as thou wilt*. Luke says it a little differently, but it is one prayer. The Son asks the Father, and the Son's will bends to the Father's.$n$,7,$n$*Father, if thou be willing, remove this cup from me: nevertheless not my will, but thine, be done* (Luke 22:42). The Gethsemane prayer — the Formed-Son's substantial submission to the Formless-Father over the cup. The cup-of-the-Father's-wrath the King about to drink, named in Yeshayahu (Isaiah) 51:17, 22; Yirmeyahu (Jeremiah) 25:15. The synoptic parallel at Matthew 26:39 carries the same Father-Son submission-substance.$n$,$n$Matthew 26:39 — *nevertheless not as I will, but as thou wilt.* Matthew records the same prayer, the cup asked away and the Son's will given over to the Father's.$n$),
(5319,'canon','mark',14,32,$n$And they came to a place which was named Gethsemane: and he says to his disciples, Sit you here, while I shall pray.$n$,'canon','isaiah',51,17,$n$thread:gethsemane-cup-of-suffering-and-the-sons-substantial-submission-to-the-father | *Awake, awake, stand up, O Yerushalayim, which hast drunk at the hand of Yahuah the cup of his fury* (Yeshayahu/Isaiah 51:17, 22).$n$,$n$Isaiah 51:17 — *Awake, awake, stand up, O Jerusalem, which hast drunk at the hand of Yahuah (LORD) the cup of his fury; thou hast drunken the dregs of the cup of trembling, and wrung them out.* *And they came to a place which was named Gethsemane: and he says to his disciples, Sit you here, while I shall pray.* (Mark 14:32) Mark brings him to a place to pray, and Isaiah shows what weight the prayer carries. Jerusalem had drunk *the cup of his fury* from the hand of Yahuah (LORD) and wrung out the dregs of it. The cup is old and it is real, and it is the Father's.$n$,7,$n$*Awake, awake, stand up, O Yerushalayim, which hast drunk at the hand of Yahuah the cup of his fury* (Yeshayahu/Isaiah 51:17, 22).$n$,$n$Isaiah 51:17 — *thou hast drunken the dregs of the cup of trembling, and wrung them out.* Jerusalem drank the dregs of the cup of trembling, so the cup he prays over was already a known and heavy thing.$n$),
(5320,'canon','mark',14,32,$n$And they came to a place which was named Gethsemane: and he says to his disciples, Sit you here, while I shall pray.$n$,'canon','jeremiah',25,15,$n$thread:gethsemane-cup-of-suffering-and-the-sons-substantial-submission-to-the-father | Yirmeyahu (Jeremiah) 25:15-17's cup-of-wrath the Father hands the nations.$n$,$n$Jeremiah 25:15 — *For thus saith Yahuah Elohim (the LORD God) of Yashar'el (Israel) unto me; Take the wine cup of this fury at my hand, and cause all the nations, to whom I send thee, to drink it.* *And they came to a place which was named Gethsemane: and he says to his disciples, Sit you here, while I shall pray.* (Mark 14:32) Mark brings him to the place of prayer, and Jeremiah shows whose cup it is. Yahuah (LORD) hands the wine cup of fury to the prophet and sends him to carry it out. The cup is poured from the hand of Yahuah (LORD) and given to whom he chooses. That is the hand the Son looks to when he prays.$n$,7,$n$Yirmeyahu (Jeremiah) 25:15-17's cup-of-wrath the Father hands the nations.$n$,$n$Jeremiah 25:15 — *Take the wine cup of this fury at my hand, and cause all the nations.* The cup of fury is given out from the hand of Yahuah (LORD), so it is his to hand over.$n$),
(5318,'canon','mark',14,32,$n$And they came to a place which was named Gethsemane: and he says to his disciples, Sit you here, while I shall pray.$n$,'canon','hebrews',5,7,$n$thread:gethsemane-cup-of-suffering-and-the-sons-substantial-submission-to-the-father | *The Formed Son's submission to the Formless Father walked out in the garden.* *Who in the days of his flesh, when he had offered up prayers and supplications with strong crying and tears* (Hebrews 5:7-9).$n$,$n$Hebrews 5:7 — *Who in the days of his flesh, when he had offered up prayers and supplications with strong crying and tears unto him that was able to save him from death, and was heard in that he feared;* *And they came to a place which was named Gethsemane: and he says to his disciples, Sit you here, while I shall pray.* (Mark 14:32) Hebrews says what the garden was. In the days of his flesh he offered prayers *with strong crying and tears* to the one able to save him from death, and he was heard. He asked, he feared, and he was heard. The Son at prayer in Mark's garden is the same Son who prayed this way.$n$,7,$n$*The Formed Son's submission to the Formless Father walked out in the garden.* *Who in the days of his flesh, when he had offered up prayers and supplications with strong crying and tears* (Hebrews 5:7-9).$n$,$n$Hebrews 5:7 — *offered up prayers and supplications with strong crying and tears unto him that was able to save him from death.* Hebrews names the garden prayer, strong crying and tears to the one able to save him from death, and says he was heard.$n$),
(5321,'canon','mark',14,38,$n$Watch you and pray, lest you enter into temptation. The spirit truly is ready, but the flesh is weak.$n$,'canon','romans',7,18,$n$thread:gethsemane-cup-of-suffering-and-the-sons-substantial-submission-to-the-father | *The spirit truly is ready, but the flesh is weak.* The body-spirit asymmetry the disciple walks under (Romans 7:18-25). The watch-and-pray charge is not abolished by the cross; it is the disciple's standing rule.$n$,$n$Romans 7:18 — *For I know that in me (that is, in my flesh,) dwelleth no good thing: for to will is present with me; but how to perform that which is good I find not.* *Watch you and pray, lest you enter into temptation. The spirit truly is ready, but the flesh is weak.* (Mark 14:38) He says the spirit is ready and the flesh is weak. Paul says the same weakness in his own words: to will is with him, but to do the good he finds not. The charge to watch and pray stands because the weakness stands. Paul also calls the law good in the same passage, so the weakness is in the flesh and not in the law.$n$,7,$n$*The spirit truly is ready, but the flesh is weak.* The body-spirit asymmetry the disciple walks under (Romans 7:18-25). The watch-and-pray charge is not abolished by the cross; it is the disciple's standing rule.$n$,$n$Romans 7:18 — *for to will is present with me; but how to perform that which is good I find not.* Paul names the same split between willing and doing that Yahusha (Jesus) gives as the reason to watch and pray.$n$),
(5322,'canon','mark',14,38,$n$Watch you and pray, lest you enter into temptation. The spirit truly is ready, but the flesh is weak.$n$,'canon','galatians',5,17,$n$thread:gethsemane-cup-of-suffering-and-the-sons-substantial-submission-to-the-father | *The flesh lusteth against the Spirit, and the Spirit against the flesh* (Galatians 5:17).$n$,$n$Galatians 5:17 — *For the flesh lusteth against the Spirit, and the Spirit against the flesh: and these are contrary the one to the other: so that ye cannot do the things that ye would.* *Watch you and pray, lest you enter into temptation. The spirit truly is ready, but the flesh is weak.* (Mark 14:38) Paul describes the same pull. The flesh wants one way and the Spirit another, and a man cannot do all he would. Yahusha (Jesus) said it to sleeping men in the garden and gave them the way through, *Watch ye and pray*. The weakness is plain, and so is the charge that goes with it.$n$,7,$n$*The flesh lusteth against the Spirit, and the Spirit against the flesh* (Galatians 5:17).$n$,$n$Galatians 5:17 — *the flesh lusteth against the Spirit, and the Spirit against the flesh.* Paul describes the same pull between flesh and Spirit that Yahusha (Jesus) names when he finds the disciples asleep.$n$),
(5323,'canon','mark',14,41,$n$And he comes the third time, and says unto them, Sleep on now, and take your rest: it is enough, the hour is come; behold, the Son of Adam is betrayed into the hands of sinners.$n$,'canon','isaiah',53,6,$n$thread:gethsemane-cup-of-suffering-and-the-sons-substantial-submission-to-the-father | *The hour is come; behold, the Son of Adam is betrayed into the hands of sinners.* *Yahuah (the LORD) hath laid on him the iniquity of us all* (Yeshayahu/Isaiah 53:6).$n$,$n$Isaiah 53:6 — *All we like sheep have gone astray; we have turned every one to his own way; and Yahuah (LORD) hath laid on him the iniquity of us all.* *And he comes the third time, and says unto them, Sleep on now, and take your rest: it is enough, the hour is come; behold, the Son of Adam is betrayed into the hands of sinners.* (Mark 14:41) The hour has come and he is handed to sinners, and Isaiah had already said who laid it on him. *All we like sheep have gone astray*, each to his own way, and it was Yahuah (LORD) who laid the weight on him. Judas does the handing, but the hand behind it is Yahuah (LORD).$n$,7,$n$*The hour is come; behold, the Son of Adam is betrayed into the hands of sinners.* *Yahuah (the LORD) hath laid on him the iniquity of us all* (Yeshayahu/Isaiah 53:6).$n$,$n$Isaiah 53:6 — *Yahuah (LORD) hath laid on him the iniquity of us all.* Isaiah says the laying of the iniquity on him was the work of Yahuah (LORD), behind the betrayal to sinners.$n$),
(5324,'canon','mark',14,43,$n$And immediately, while he yet spake, comes Judas, one of the twelve, and with him a great multitude with swords and staves, from the chief priests and the scribes and the elders.$n$,'canon','zechariah',13,7,$n$thread:gethsemane-cup-of-suffering-and-the-sons-substantial-submission-to-the-father | *The scriptures must be fulfilled.* Zecharyah (Zechariah) 13:7's smiting of the shepherd; the disciples scattering is the script the King quoted moments before.$n$,$n$Zechariah 13:7 — *Awake, O sword, against my shepherd, and against the man that is my fellow, saith Yahuah Tseva'ot (LORD of hosts): smite the shepherd, and the sheep shall be scattered: and I will turn mine hand upon the little ones.* *And immediately, while he yet spake, comes Judas, one of the twelve, and with him a great multitude with swords and staves, from the chief priests and the scribes and the elders.* (Mark 14:43) Judas comes with swords and staves, and Zechariah had already heard the order given. Yahuah (LORD) calls the sword against the shepherd, and the sheep are scattered. The crowd with its weapons is the sword the prophet saw. The scattered are *the little ones* his hand turns toward.$n$,7,$n$*The scriptures must be fulfilled.* Zecharyah (Zechariah) 13:7's smiting of the shepherd; the disciples scattering is the script the King quoted moments before.$n$,$n$Zechariah 13:7 — *smite the shepherd, and the sheep shall be scattered: and I will turn mine hand upon the little ones.* Zechariah has the shepherd struck and the sheep scattered, and the hand that strikes then turns toward the little ones.$n$),
(5352,'canon','mark',15,37,$n$And Yahusha (Jesus) cried with a loud voice, and gave up the ghost.$n$,'canon','luke',23,46,$n$thread:gethsemane-cup-of-suffering-and-the-sons-substantial-submission-to-the-father | *Father, into thy hands I commend my spirit* (Luke 23:46).$n$,$n$Luke 23:46 — *And when Yahusha (Jesus) had cried with a loud voice, he said, Father, into thy hands I commend my spirit: and having said thus, he gave up the ghost.* *And Yahusha (Jesus) cried with a loud voice, and gave up the ghost.* (Mark 15:37) Mark gives only the loud cry and the giving up of the ghost. Luke tells what the cry was: *Father, into thy hands I commend my spirit*. The last thing he does is what he did in the garden. He gives himself over to the Father.$n$,7,$n$*Father, into thy hands I commend my spirit* (Luke 23:46).$n$,$n$Luke 23:46 — *Father, into thy hands I commend my spirit: and having said thus, he gave up the ghost.* Luke gives the words of the loud cry, the spirit handed into the Father's hands.$n$),
(5351,'canon','mark',15,37,$n$And Yahusha (Jesus) cried with a loud voice, and gave up the ghost.$n$,'canon','john',10,18,$n$thread:gethsemane-cup-of-suffering-and-the-sons-substantial-submission-to-the-father | *Yahusha cried with a loud voice, and gave up the ghost.* *No man taketh it from me, but I lay it down of myself* (Yochanan/John 10:18).$n$,$n$John 10:18 — *No man taketh it from me, but I lay it down of myself. I have power to lay it down, and I have power to take it again. This commandment have I received of my Father.* *And Yahusha (Jesus) cried with a loud voice, and gave up the ghost.* (Mark 15:37) He gave up the ghost, and John says no one took it from him. *I lay it down of myself*, he says, and he had the power to take it up again. It was a commandment from his Father. So the loud cry is a Son keeping a charge, not a man overpowered.$n$,7,$n$*Yahusha cried with a loud voice, and gave up the ghost.* *No man taketh it from me, but I lay it down of myself* (Yochanan/John 10:18).$n$,$n$John 10:18 — *No man taketh it from me, but I lay it down of myself.* No one takes the life from him. He lays it down by the Father's commandment, so the death is the Son's own act of obedience.$n$);
CREATE TEMP TABLE s503c_thread (id bigint, slug text, old_title text, new_title text, old_summary text, new_summary text) ON COMMIT DROP;
INSERT INTO s503c_thread VALUES (7, 'gethsemane-cup-of-suffering-and-the-sons-substantial-submission-to-the-father', $n$Gethsemane Cup Of Suffering And The Sons Substantial Submission To The Father$n$, $n$Gethsemane — the cup in the Father's hand, and not as I will, but as thou wilt (Psalm 75; Isaiah 51; John 10; Hebrews 5; Zechariah 13)$n$, $n$**`gethsemane-cup-of-suffering-and-the-sons-substantial-submission-to-the-father`** — anchor at Matt 26:36-46. The substantial-Gethsemane substance + the substantial-cup-of-suffering substance per `cup-of-suffering-tanakh-substance` thread (PROPOSED at Matt 20 from S85) + the substantial-Son's-submission-to-the-Father per the Formless-Formed grid per `nature-of-god-formed-in-flesh` thread. Framework rules out Trinitarian-three-co-equal-persons + modalist-collapse + Arian-created-being; the substantial-Son's-eternal-submission preserved in incarnation. 16 members.$n$, $n$It ain't new. The cup he prayed over in the garden was already in the Father's hand in the Psalms and the prophets, and the prayer itself, not my will but thine, is what the Son had said of himself all along. Matthew sets the scene:

*Then cometh Yahusha (Jesus) with them unto a place called Gethsemane, and saith unto the disciples, Sit ye here, while I go and pray yonder.* (Matthew 26:36)

*Then saith he unto them, My soul is exceeding sorrowful, even unto death: tarry ye here, and watch with me.* (Matthew 26:38)

*And he went a little further, and fell on his face, and prayed, saying, O my Father, if it be possible, let this cup pass from me: nevertheless not as I will, but as thou wilt.* (Matthew 26:39)

The soul cast down was the psalmist's before it was his:

*Why art thou cast down, O my soul? and why art thou disquieted in me? hope thou in Elohim (God): for I shall yet praise him for the help of his countenance.* (Psalm 42:5)

And the cup is not a figure Matthew made up. It is the cup of fury in the hand of Yahuah (LORD), poured out and drunk to the dregs:

*For in the hand of Yahuah (LORD) there is a cup, and the wine is red; it is full of mixture; and he poureth out of the same: but the dregs thereof, all the wicked of the earth shall wring them out, and drink them.* (Psalm 75:8)

*Awake, awake, stand up, O Jerusalem, which hast drunk at the hand of Yahuah (LORD) the cup of his fury; thou hast drunken the dregs of the cup of trembling, and wrung them out.* (Isaiah 51:17)

*Thus saith thy Yahuah (Lord) Yahuah (LORD), and thy Elohim (God) that pleadeth the cause of his people, Behold, I have taken out of thine hand the cup of trembling, even the dregs of the cup of my fury; thou shalt no more drink it again:* (Isaiah 51:22)

Isaiah says the cup is taken out of Jerusalem's hand. In the garden it is put into his. He had already asked the sons of Zebedee whether they could drink it:

*But Yahusha (Jesus) answered and said, Ye know not what ye ask. Are ye able to drink of the cup that I shall drink of, and to be baptized with the baptism that I am baptized with? They say unto him, We are able.* (Matthew 20:22)

Luke adds the angel and the sweat:

*Saying, Father, if thou be willing, remove this cup from me: nevertheless not my will, but thine, be done.* (Luke 22:42)

*And there appeared an angel unto him from heaven, strengthening him.* (Luke 22:43)

*And being in an agony he prayed more earnestly: and his sweat was as it were great drops of blood falling down to the ground.* (Luke 22:44)

Read what the prayer is. It is the Son asking the Father, and the Son's will bending to the Father's will. He is Elohim (God), and he has a Father, and he does the Father's will. He said so before the garden, said it in the garden, and said it from the cross:

*Then answered Yahusha (Jesus) and said unto them, Verily, verily, I say unto you, The Son can do nothing of himself, but what he seeth the Father do: for what things soever he doeth, these also doeth the Son likewise.* (John 5:19)

*Now is my soul troubled; and what shall I say? Father, save me from this hour: but for this cause came I unto this hour.* (John 12:27)

*And when Yahusha (Jesus) had cried with a loud voice, he said, Father, into thy hands I commend my spirit: and having said thus, he gave up the ghost.* (Luke 23:46)

Nobody took the life from him. The cup was drunk because he chose to drink it, and the choosing was the Father's commandment kept:

*No man taketh it from me, but I lay it down of myself. I have power to lay it down, and I have power to take it again. This commandment have I received of my Father.* (John 10:18)

Hebrews says plainly what the garden was:

*Who in the days of his flesh, when he had offered up prayers and supplications with strong crying and tears unto him that was able to save him from death, and was heard in that he feared;* (Hebrews 5:7)

*Though he were a Son, yet learned he obedience by the things which he suffered;* (Hebrews 5:8)

And Paul says that same mind is the one we are to carry:

*Let this mind be in you, which was also in HaMashiach Yahusha (Christ Jesus):* (Philippians 2:5)

*And being found in fashion as a man, he humbled himself, and became obedient unto death, even the death of the cross.* (Philippians 2:8)

Set Abraham beside it. He also rose early and went up the mountain with his only son, and Matthew does not say the word; put the two side by side and read:

*And he said, Take now thy son, thine only son Isaac, whom thou lovest, and get thee into the land of Moriah; and offer him there for a burnt offering upon one of the mountains which I will tell thee of.* (Genesis 22:2)

Then the hour comes, the shepherd is struck as Zechariah said, and the sheep run:

*Then cometh he to his disciples, and saith unto them, Sleep on now, and take your rest: behold, the hour is at hand, and the Son of Adam is betrayed into the hands of sinners.* (Matthew 26:45)

*Awake, O sword, against my shepherd, and against the man that is my fellow, saith Yahuah Tseva'ot (LORD of hosts): smite the shepherd, and the sheep shall be scattered: and I will turn mine hand upon the little ones.* (Zechariah 13:7)

The sheep who scattered that night are the little ones his hand turns toward. They slept while he prayed, and the charge he gave them in the garden is still the charge:

*Watch and pray, that ye enter not into temptation: the spirit indeed is willing, but the flesh is weak.* (Matthew 26:41)$n$);

DO $s503c$
DECLARE r record; x record; n int;
BEGIN
  FOR r IN SELECT * FROM s503c_cards LOOP
    SELECT xr.id, xr.note, sv.text AS stext, se.slug AS sed, sb.slug AS sbook, sc.chapter_number AS sch, sv.verse_number AS svn, te.slug AS ted, tb.slug AS tbook, tc.chapter_number AS tch, tv.verse_number AS tvn
      INTO x FROM cross_references xr
      JOIN verses sv ON sv.id = xr.source_verse_id JOIN chapters sc ON sc.id = sv.chapter_id JOIN books sb ON sb.id = sc.book_id JOIN editions se ON se.id = sb.edition_id
      JOIN verses tv ON tv.id = xr.target_verse_id JOIN chapters tc ON tc.id = tv.chapter_id JOIN books tb ON tb.id = tc.book_id JOIN editions te ON te.id = tb.edition_id
      WHERE xr.id = r.id;
    IF NOT FOUND THEN RAISE EXCEPTION 'S503c: card % is gone', r.id; END IF;
    IF x.sed <> r.s_ed OR x.sbook <> r.s_book OR x.sch <> r.src_ch OR x.svn <> r.src_vn OR x.ted <> r.t_ed OR x.tbook <> r.tgt_book OR x.tch <> r.tgt_ch OR x.tvn <> r.tgt_vn THEN
      RAISE EXCEPTION 'S503c: card % no longer sits on the verse pair this was written for', r.id; END IF;
    IF x.stext <> r.src_text THEN RAISE EXCEPTION 'S503c: live text of % %:% differs from the read-back — re-dump and rebuild', r.s_book, r.src_ch, r.src_vn; END IF;
    IF x.note IS DISTINCT FROM r.old_note AND x.note IS DISTINCT FROM r.new_note THEN RAISE EXCEPTION 'S503c: the live note of card % differs from the read-back — re-dump and rebuild', r.id; END IF;
    SELECT count(*) INTO n FROM cross_reference_thread_members m WHERE m.cross_reference_id = r.id AND m.thread_id = r.thread_id AND (m.member_note IS NOT DISTINCT FROM r.old_mnote OR m.member_note IS NOT DISTINCT FROM r.new_mnote);
    IF n <> 1 THEN RAISE EXCEPTION 'S503c: card % has no member row in thread % carrying the member note this was written against', r.id, r.thread_id; END IF;
  END LOOP;
  SELECT t.* INTO x FROM cross_reference_threads t JOIN s503c_thread s ON s.id = t.id AND s.slug = t.slug;
  IF NOT FOUND THEN RAISE EXCEPTION 'S503c: thread 7 not found under its slug'; END IF;
  SELECT count(*) INTO n FROM cross_reference_threads t JOIN s503c_thread s ON s.id = t.id
    WHERE (t.title = s.old_title AND t.summary_md = s.old_summary) OR (t.title = s.new_title AND t.summary_md = s.new_summary);
  IF n <> 1 THEN RAISE EXCEPTION 'S503c: thread 7 title/summary differ from the read-back — re-dump and rebuild'; END IF;
END $s503c$;

DO $s503c2$
DECLARE n_notes int; n_m int; n_t int; n_c int;
BEGIN
  SELECT count(*) INTO n_c FROM s503c_cards;
  UPDATE cross_references xr SET note = c.new_note FROM s503c_cards c WHERE xr.id = c.id AND xr.note IS NOT DISTINCT FROM c.old_note AND c.old_note IS DISTINCT FROM c.new_note;
  GET DIAGNOSTICS n_notes = ROW_COUNT;
  UPDATE cross_reference_thread_members m SET member_note = c.new_mnote FROM s503c_cards c WHERE m.cross_reference_id = c.id AND m.thread_id = c.thread_id AND m.member_note IS NOT DISTINCT FROM c.old_mnote AND c.old_mnote IS DISTINCT FROM c.new_mnote;
  GET DIAGNOSTICS n_m = ROW_COUNT;
  UPDATE cross_reference_threads t SET title = s.new_title, summary_md = s.new_summary FROM s503c_thread s WHERE t.id = s.id AND t.title = s.old_title AND t.summary_md = s.old_summary AND (s.old_title <> s.new_title OR s.old_summary <> s.new_summary);
  GET DIAGNOSTICS n_t = ROW_COUNT;
  RAISE NOTICE 'S503c (gethsemane-cup-of-suffering) summary: notes rewritten % / already there %; member notes rewritten % / already there %; thread rewritten % / already there %', n_notes, n_c - n_notes, n_m, n_c - n_m, n_t, 1 - n_t;
END $s503c2$;
COMMIT;
\echo 'session503c — gethsemane-cup-of-suffering done.'
